metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "ko"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "method",
        "text": "life_step(grid)"
      },
      "body": [
        {
          "id": "b1",
          "kind": "process",
          "text": "rows, cols = len(grid), len(grid[0])"
        },
        {
          "id": "b2",
          "kind": "process",
          "text": "nxt = [[0] * cols for _ in range(rows)]    # 다음 세대는 새 판에"
        },
        {
          "id": "b3",
          "kind": "for",
          "text": "for r in range(rows)",
          "body": [
            {
              "id": "b4",
              "kind": "for",
              "text": "for c in range(cols)",
              "body": [
                {
                  "id": "b5",
                  "kind": "call",
                  "target": {
                    "kind": "local",
                    "diagram": "d2"
                  },
                  "args": "grid, r, c",
                  "result": "n"
                },
                {
                  "id": "b6",
                  "kind": "case",
                  "text": "n",
                  "arms": [
                    {
                      "id": "r1",
                      "label": "2",
                      "body": [
                        {
                          "id": "b7",
                          "kind": "process",
                          "text": "nxt[r][c] = grid[r][c]    # 산 칸은 살고 빈 칸은 그대로"
                        }
                      ]
                    },
                    {
                      "id": "r2",
                      "label": "3",
                      "body": [
                        {
                          "id": "b8",
                          "kind": "process",
                          "text": "nxt[r][c] = 1    # 태어나거나 산다"
                        }
                      ]
                    }
                  ],
                  "otherwise": {
                    "id": "r3",
                    "body": [
                      {
                        "id": "b9",
                        "kind": "process",
                        "text": "nxt[r][c] = 0    # 외로움이나 과밀로 죽는다"
                      }
                    ]
                  }
                }
              ]
            }
          ]
        },
        {
          "id": "b10",
          "kind": "process",
          "text": "return nxt"
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "live_neighbors(grid, r, c)"
      },
      "body": [
        {
          "id": "b11",
          "kind": "process",
          "text": "rows, cols = len(grid), len(grid[0])"
        },
        {
          "id": "b12",
          "kind": "process",
          "text": "n = 0"
        },
        {
          "id": "b13",
          "kind": "for",
          "text": "for dr in (-1, 0, 1)",
          "body": [
            {
              "id": "b14",
              "kind": "for",
              "text": "for dc in (-1, 0, 1)",
              "body": [
                {
                  "id": "b15",
                  "kind": "if",
                  "text": "(dr, dc) != (0, 0)",
                  "yes": {
                    "id": "r4",
                    "body": [
                      {
                        "id": "b16",
                        "kind": "process",
                        "text": "n += grid[(r + dr) % rows][(c + dc) % cols]    # 가장자리는 맞은편과 이어진다"
                      }
                    ]
                  },
                  "no": {
                    "id": "r5",
                    "body": [
                      {
                        "id": "b17",
                        "kind": "process",
                        "text": ""
                      }
                    ]
                  }
                }
              ]
            }
          ]
        },
        {
          "id": "b18",
          "kind": "process",
          "text": "return n"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
